            targetUrl = validateUrl(trimmedUrl);
        } catch (MalformedURLException e) {
            LOGGER.log(Level.WARNING,
                    "Malformed URL rejected: [" + trimmedUrl + "]", e);
            return null;
        } catch (SecurityException e) {
            LOGGER.log(Level.WARNING,
                    "Unsafe URL blocked: [" + trimmedUrl + "] - "
                            + e.getMessage(), e);
            return null;
