                    "text/html,application/xhtml+xml,"
                            + "application/xml;q=0.9,*/*;q=0.8");
            httpGet.setHeader("Accept-Language", "en-US,en;q=0.5");

            try (CloseableHttpResponse response = httpClient.execute(httpGet)) {

                int statusCode = response.getStatusLine().getStatusCode();

                // Only accept 2xx responses
                if (statusCode < HttpStatus.SC_OK
                        || statusCode >= HttpStatus.SC_MULTIPLE_CHOICES) {
                    LOGGER.log(Level.FINE,
                            "Non-success status code {0} for URL [{1}]",
                            new Object[]{statusCode, trimmedUrl});
                    return null;
                }

                HttpEntity entity = response.getEntity();
                if (entity == null) {
                    LOGGER.log(Level.FINE,
                            "Empty response entity for URL [{0}]", trimmedUrl);
                    return null;
                }

                // Check content length to avoid OutOfMemoryError
                long contentLength = entity.getContentLength();
                if (contentLength > MAX_RESPONSE_SIZE_BYTES) {
                    LOGGER.log(Level.WARNING,
                            "Response too large ({0} bytes) for URL [{1}]; "
                                    + "max allowed is {2} bytes",
                            new Object[]{contentLength, trimmedUrl,
                                    MAX_RESPONSE_SIZE_BYTES});
                    EntityUtils.consumeQuietly(entity);
                    return null;
                }

                Charset charset = detectCharset(entity);

                // Read with a size guard (EntityUtils.toString with a max
                // length would be ideal, but we simulate it here)
                byte[] rawBytes = EntityUtils.toByteArray(entity);
                if (rawBytes.length > MAX_RESPONSE_SIZE_BYTES) {
                    LOGGER.log(Level.WARNING,
                            "Actual response size ({0} bytes) exceeds "
                                    + "limit for URL [{1}]",
                            new Object[]{rawBytes.length, trimmedUrl});
                    return null;
                }

                return new String(rawBytes, charset);

            } // response auto-closed here

        } catch (IOException e) {
            LOGGER.log(Level.WARNING,
                    "I/O error while fetching URL [" + trimmedUrl + "]: "
                            + e.getMessage(), e);
            return null;
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE,
                    "Unexpected error while fetching URL [" + trimmedUrl + "]",
                    e);
            return null;
        }
    }
}

