                    || addr.isAnyLocalAddress()        // 0.0.0.0, ::
                    ) {
                return true;
            }
            // Additional check for IPv6 Unique Local Addresses (fc00::/7)
            if (addr instanceof Inet6Address) {
                byte[] bytes = addr.getAddress();
