import org.apache.http.util.EntityUtils;

import java.io.IOException;
import java.nio.charset.StandardCharsets;

public class UrlService {

    /**
     * Fetches the content of the given URL as a plain text string.
     *
     * @param userUrl the URL to fetch, must not be null or empty
     * @return the response body as a string (UTF-8)
     * @throws IllegalArgumentException if the provided URL is null or empty
     * @throws UrlFetchException if the request fails or the response indicates a non‑2xx status
     */
    public String fetchUrlContent(String userUrl) {
        if (userUrl == null || userUrl.isEmpty()) {
            throw new IllegalArgumentException("URL must not be null or empty");
        }

        HttpGet httpGet = new HttpGet(userUrl);

        try (CloseableHttpClient httpClient = HttpClients.createDefault();
             CloseableHttpResponse response = httpClient.execute(httpGet)) {

            int statusCode = response.getStatusLine().getStatusCode();
            if (statusCode < 200 || statusCode >= 300) {
                throw new UrlFetchException(
                    "Failed to fetch URL: HTTP " + statusCode + " " +
                    response.getStatusLine().getReasonPhrase()
                );
            }

            return EntityUtils.toString(response.getEntity(), StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UrlFetchException("Error fetching URL content: " + e.getMessage(), e);
        }
    }

    /**
     * Custom runtime exception for URL fetching failures.
     */
    public static class UrlFetchException extends RuntimeException {
        public UrlFetchException(String message) {
            super(message);
        }

        public UrlFetchException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}

